    tensor cat276 = ggml_concat(m, dwconv274, dwconv275, 2);
    tensor bn277 = batch_norm_2d(m["backbone.level2.13.bn"], cat276);
    tensor prelu278 = prelu(m["backbone.level2.13.activate"], bn277);
    tensor pool279 = ggml_pool_2d(m, prelu278, GGML_OP_POOL_AVG, 85, 85, 85, 85, 0, 0);
    tensor rs280 = ggml_reshape_2d(m, ggml_cont(m, pool279), 128, 1);
    tensor fc281 = linear(m["backbone.level2.13.f_glo.fc.0"], rs280);
    tensor act282 = ggml_relu(m, fc281);
    tensor fc283 = linear(m["backbone.level2.13.f_glo.fc.2"], act282);
    tensor act284 = ggml_sigmoid(m, fc283);
    tensor rs285 = ggml_reshape_4d(m, ggml_cont(m, act284), 1, 1, 128, 1);
    tensor t286 = ggml_mul(m, as_f32(m, prelu278), as_f32(m, rs285));
    tensor add287 = ggml_add(m, add271, t286);
    tensor conv288 = conv_2d(m["backbone.level2.14.conv1x1.conv"], add287, 1, 0);
