    tensor cat308 = ggml_concat(m, dwconv306, dwconv307, 2);
    tensor bn309 = batch_norm_2d(m["backbone.level2.15.bn"], cat308);
    tensor prelu310 = prelu(m["backbone.level2.15.activate"], bn309);
    tensor pool311 = ggml_pool_2d(m, prelu310, GGML_OP_POOL_AVG, 85, 85, 85, 85, 0, 0);
    tensor rs312 = ggml_reshape_2d(m, ggml_cont(m, pool311), 128, 1);
    tensor fc313 = linear(m["backbone.level2.15.f_glo.fc.0"], rs312);
    tensor act314 = ggml_relu(m, fc313);
    tensor fc315 = linear(m["backbone.level2.15.f_glo.fc.2"], act314);
    tensor act316 = ggml_sigmoid(m, fc315);
    tensor rs317 = ggml_reshape_4d(m, ggml_cont(m, act316), 1, 1, 128, 1);
    tensor t318 = ggml_mul(m, as_f32(m, prelu310), as_f32(m, rs317));
    tensor add319 = ggml_add(m, add303, t318);
    tensor conv320 = conv_2d(m["backbone.level2.16.conv1x1.conv"], add319, 1, 0);
    tensor prelu321 = prelu(m["backbone.level2.16.conv1x1.activate"], conv320);
    tensor dwconv322 = conv_2d_depthwise(m["backbone.level2.16.f_loc"], prelu321, 1, 1);
