    tensor cat324 = ggml_concat(m, dwconv322, dwconv323, 2);
    tensor bn325 = batch_norm_2d(m["backbone.level2.16.bn"], cat324);
    tensor prelu326 = prelu(m["backbone.level2.16.activate"], bn325);
    tensor pool327 = ggml_pool_2d(m, prelu326, GGML_OP_POOL_AVG, 85, 85, 85, 85, 0, 0);
    tensor rs328 = ggml_reshape_2d(m, ggml_cont(m, pool327), 128, 1);
    tensor fc329 = linear(m["backbone.level2.16.f_glo.fc.0"], rs328);
    tensor act330 = ggml_relu(m, fc329);
    tensor fc331 = linear(m["backbone.level2.16.f_glo.fc.2"], act330);
    tensor act332 = ggml_sigmoid(m, fc331);
    tensor rs333 = ggml_reshape_4d(m, ggml_cont(m, act332), 1, 1, 128, 1);
    tensor t334 = ggml_mul(m, as_f32(m, prelu326), as_f32(m, rs333));
    tensor add335 = ggml_add(m, add319, t334);
    tensor conv336 = conv_2d(m["backbone.level2.17.conv1x1.conv"], add335, 1, 0);
    tensor prelu337 = prelu(m["backbone.level2.17.conv1x1.activate"], conv336);
    tensor dwconv338 = conv_2d_depthwise(m["backbone.level2.17.f_loc"], prelu337, 1, 1);
    tensor dwconv339 = conv_2d_depthwise(m["backbone.level2.17.f_sur"], prelu337, 1, 4, 4);
    tensor cat340 = ggml_concat(m, dwconv338, dwconv339, 2);
    tensor bn341 = batch_norm_2d(m["backbone.level2.17.bn"], cat340);
    tensor prelu342 = prelu(m["backbone.level2.17.activate"], bn341);
    tensor pool343 = ggml_pool_2d(m, prelu342, GGML_OP_POOL_AVG, 85, 85, 85, 85, 0, 0);
